@Component("beneficiary-handler")
@ProcessingGroup("beneficiary-processing-group")
public class BeneficiaryEventHandler {
	
	// core constructor
	BeneficiaryEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBeneficiaryEvent
     */
    @EventHandler
    public void handle( CreateBeneficiaryEvent event) {
        entityManager.persist(new Beneficiary(event.getBeneficiaryId(), event.getName(), event.getAccountIdentifier(), event.getIban(), event.getBic(), event.getAddress(), event.getCustomer()));
    }

    /*
     * @param	event UpdateBeneficiaryEvent
     */
    @EventHandler
    public Beneficiary handle( UpdateBeneficiaryEvent event) {
    	entityManager.merge(new Beneficiary(event.getBeneficiaryId(), event.getName(), event.getAccountIdentifier(), event.getIban(), event.getBic(), event.getAddress(), event.getCustomer()));
    }
    
    /*
     * @param	event DeleteBeneficiaryEvent
     */
    @EventHandler
    public void on( DeleteBeneficiaryEvent event) {
    	Beneficiary entity = new Beneficiary();
   
    	// ------------------------------------------
    	// apply the BeneficiaryId
    	// ------------------------------------------
    	entity.setBeneficiaryId( event.getBeneficiaryId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BeneficiaryRepository beneficiaryEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BeneficiaryEventHandler.class.getName());

}
